STATEMENTS = (
    "CREATE TABLE production_orders(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT NOT NULL UNIQUE,printer_id INTEGER NOT NULL REFERENCES printers(id),item_id INTEGER REFERENCES order_items(id),parent_id INTEGER REFERENCES production_orders(id),created_at TEXT NOT NULL,priority TEXT NOT NULL CHECK(priority IN('high','normal','low')),position INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN('waiting','printing','inspection','completed')),responsible TEXT NOT NULL,parameters TEXT NOT NULL,planned TEXT NOT NULL,started_at TEXT,revision INTEGER NOT NULL DEFAULT 1,cost_consolidated INTEGER NOT NULL DEFAULT 0)",
    "CREATE TABLE production_entries(id INTEGER PRIMARY KEY AUTOINCREMENT,op_id INTEGER NOT NULL REFERENCES production_orders(id),variant_id INTEGER NOT NULL REFERENCES variants(id),project_id INTEGER NOT NULL REFERENCES project_versions(id),quantity INTEGER NOT NULL CHECK(quantity>0),category TEXT NOT NULL,planned TEXT NOT NULL)",
    "CREATE TABLE production_attempts(id INTEGER PRIMARY KEY AUTOINCREMENT,op_id INTEGER NOT NULL REFERENCES production_orders(id),created_at TEXT NOT NULL,minutes INTEGER NOT NULL CHECK(minutes>=0),progress TEXT NOT NULL,reason TEXT NOT NULL,actual TEXT NOT NULL,operation_key TEXT NOT NULL UNIQUE)",
    "CREATE TABLE production_pieces(piece_id INTEGER PRIMARY KEY REFERENCES pieces(id),entry_id INTEGER NOT NULL REFERENCES production_entries(id),attempt_id INTEGER NOT NULL REFERENCES production_attempts(id))",
    "CREATE TABLE inspections(id INTEGER PRIMARY KEY AUTOINCREMENT,piece_id INTEGER NOT NULL REFERENCES pieces(id),revision INTEGER NOT NULL,created_at TEXT NOT NULL,responsible TEXT NOT NULL,result TEXT NOT NULL CHECK(result IN('approved','notes','rejected')),checklist TEXT NOT NULL,notes TEXT NOT NULL,valid INTEGER NOT NULL DEFAULT 1 CHECK(valid IN(0,1)))",
    "CREATE TABLE inspection_photos(id INTEGER PRIMARY KEY AUTOINCREMENT,inspection_id INTEGER NOT NULL REFERENCES inspections(id),view TEXT NOT NULL CHECK(view IN('front','back','detail')),path TEXT NOT NULL UNIQUE,sha256 TEXT NOT NULL,UNIQUE(inspection_id,view))",
    "CREATE TABLE production_problems(id INTEGER PRIMARY KEY AUTOINCREMENT,op_id INTEGER NOT NULL REFERENCES production_orders(id),product_id INTEGER NOT NULL REFERENCES products(id),created_at TEXT NOT NULL,kind TEXT NOT NULL,description TEXT NOT NULL,responsible TEXT NOT NULL)",
    "CREATE INDEX production_queue ON production_orders(state,priority,position)",
)
